function renderBanner(){const insignia=data[era].insignia,box=el('historyBanner');box.hidden=!insignia||done();if(!box.hidden){el('historyBannerImage').src=insignia.image;el('historyBannerImage').alt=insignia.alt;el('historyBannerLabel').textContent=insignia.label}}
