async function show(which){if(busy)return;busy=true;const token=++request;try{if(!data){const r=await fetch('historical.json?v=20261031-republic-expanded');if(!r.ok)throw Error('Historical map unavailable');data=await r.json();await Promise.all(Object.keys(data).map(async key=>{const values=await Promise.all(['','-labels'].map(async suffix=>{const r=await fetch(key+'-territories'+suffix+'.geojson?v=20261031-republic-expanded');if(!r.ok)throw Error('Historical map unavailable');return r.json()}));territories[key]=values[0];labelData[key]=values[1]}))}if(token!==request)return;era=which;el('historyEra').value=era;if(typeof cancelAdvance==='function')cancelAdvance();if(typeof setMapActive==='function')setMapActive(false);hidden=[...document.querySelectorAll('.collection,.game-layout,#countryFacts,.stats,#review,#profileDialog')].map(node=>[node,node.hidden]);for(const [node]of hidden)node.hidden=true;open=true;root.hidden=false;restart();await setupMap();root.scrollIntoView({behavior:'instant',block:'start'})}catch(e){el(which+'Open').textContent='Retry historical atlas';console.error(e)}finally{busy=false}}
